  "content": {
    "format": "openapi-3.1",
    "title": "TideGlass Marine \u2014 a fleet telemetry platform that ingests AIS positions and engine-health pings from cargo vessels and exposes them through a partner REST API. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the TideGlass Marine \u2014 a fleet telemetry platform that ingests AIS positions and engine-health pings from cargo vessels and exposes them through a partner REST API. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "TideGlass Marine \u2014 a fleet telemetry platform that ingests AIS positions and engine-health pings from cargo vessels and exposes them through a partner REST API. API",
        "version": "1.0.0",
        "description": "TideGlass Telemetry API v3: vessel position history, voyage records, and an alert-acknowledgement workflow consumed by port-operations integrators."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials token",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/positions": {
          "get": {
            "summary": "Vessel position history",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vessels/{id}": {
          "get": {
            "summary": "Vessel detail",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{id}": {
          "get": {
            "summary": "Alert detail / ack state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{id}/ack": {
          "post": {
            "summary": "Acknowledge alert (commit)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-30T02:00:51.834727+00:00"
}
